<script setup lang="ts">
import { contributorsFor } from '#shared/wiki'
import { Badge } from '@commonplace/ui/badge'
import { Button as UiButton } from '@commonplace/ui/button'
const { t, resourceLabel, kindLabel, formatDate } = useI18n()
const route = useRoute()
const wiki = await useWiki()
const note = computed(() => wiki.value.get(String(route.params.id)))
if (!note.value) throw createError({ statusCode: 404, statusMessage: t('noteMissing') })
const backlinks = computed(() => wiki.value.backlinks(note.value!.noteId))
const related = computed(() => wiki.value.neighbors(note.value!.noteId))
const graph = computed(() => wiki.value.graph(note.value!.noteId))
const feedback = ref<'linkCopied' | 'markdownCopied' | 'copyFailed'>()
const { public: { audience } } = useRuntimeConfig()
async function copy(kind: 'link' | 'markdown') {
  try { await navigator.clipboard.writeText(kind === 'link' ? window.location.href : note.value!.markdown); feedback.value = kind === 'link' ? 'linkCopied' : 'markdownCopied' }
  catch { feedback.value = 'copyFailed' }
}
useSeoMeta({ title: () => `${note.value?.title} · Commonplace`, description: () => note.value?.description })
</script>
<template><WikiShell><div v-if="note" class="article-page"><div class="article-breadcrumb eyebrow"><NuxtLink to="/">{{ t('library') }}</NuxtLink><span>/</span><span>{{ note.kind === 'source' ? resourceLabel(note.resourceType) : kindLabel(note.kind) }}</span><span>/</span><span>{{ note.title }}</span></div><div class="article-layout"><article><header class="article-header"><span class="eyebrow"><i class="kind-dot" :class="note.kind" />{{ note.kind === 'source' ? resourceLabel(note.resourceType) : kindLabel(note.kind) }} <Badge v-if="note.demo" class="sample-label">{{ t('sample') }}</Badge></span><h1>{{ note.title }}</h1><p class="article-description">{{ note.description }}</p><div class="article-meta"><div><span class="eyebrow">{{ t('updated') }}</span><span>└ {{ formatDate(note.updated) }}</span></div><div><span class="eyebrow">{{ t('readingTime') }}</span><span>└ {{ t('minutes', { count: note.readingMinutes }) }}</span></div><div><span class="eyebrow">{{ t('connections') }}</span><span>└ {{ related.length }} {{ t('notes') }}</span></div></div><a v-if="note.sourceUrl" class="text-link" :href="note.sourceUrl" target="_blank" rel="noopener noreferrer">↗ {{ t('openOriginal') }}</a><ul v-if="note.kind === 'source' && contributorsFor(note).length" class="contributor-list" :aria-label="t('contributors')"><li v-for="credit in contributorsFor(note)" :key="credit.id"><NuxtLink :to="`/authors/${credit.id}`" class="author-link"><span class="contributor-initial" aria-hidden="true">{{ Array.from(credit.name)[0] }}</span><span><span class="contributor-name">{{ credit.name }}</span><span class="eyebrow">{{ credit.roles.map(role => t(`credit_${role}`)).join(' · ') }}</span></span><span aria-hidden="true">↗</span></NuxtLink></li></ul><div class="tags"><span v-for="tag in note.tags" :key="tag">#{{ tag }}</span></div></header><WikiDocument :document="note.document" /><section class="backlinks" aria-labelledby="backlinks-title"><div class="section-heading"><h2 id="backlinks-title">{{ t('backlinksTitle') }}</h2><span class="eyebrow">{{ backlinks.length }} {{ t('backlinks') }}</span></div><NuxtLink v-for="backlink in backlinks" :key="backlink.noteId" :to="`/notes/${backlink.noteId}`"><span>↖ {{ backlink.title }}</span><span class="eyebrow">{{ kindLabel(backlink.kind) }}</span></NuxtLink><p v-if="!backlinks.length">{{ t('noBacklinks') }}</p></section></article><aside class="context-rail" :aria-label="t('noteContext')"><div class="context-sticky"><div class="context-heading eyebrow">{{ t('connected') }} <NuxtLink to="/graph">↗</NuxtLink></div><ClientOnly><KnowledgeGraph :graph="graph" :active="note.noteId" :height="220" compact @open="navigateTo(`/notes/${$event}`)" /><template #fallback><div class="graph-placeholder small" /></template></ClientOnly><div class="context-links"><NuxtLink v-for="neighbor in related" :key="neighbor.noteId" :to="`/notes/${neighbor.noteId}`"><i class="kind-dot" :class="neighbor.kind" />{{ neighbor.title }}</NuxtLink></div><nav class="toc" :aria-label="t('toc')"><span class="eyebrow">{{ t('onThisPage') }}</span><a v-for="heading in note.headings" :key="heading.id" :href="`#${heading.id}`">└ {{ heading.text }}</a></nav><div class="share-actions"><span class="eyebrow">{{ audience === 'personal' ? t('localEdition') : t('share') }}</span><UiButton variant="plain" size="inherit" @click="copy('link')">└ {{ audience === 'personal' ? t('copyLocal') : t('copyLink') }}</UiButton><UiButton variant="plain" size="inherit" @click="copy('markdown')">└ {{ t('copyMarkdown') }}</UiButton><span role="status" class="copy-feedback">{{ feedback ? t(feedback) : '' }}</span></div></div></aside></div></div></WikiShell></template>
